// =====================================================================
// CONFIGURACIÓN DEL RECORDATORIO DE PENDIENTES
// =====================================================================
return [{
  json: {
    CHATWOOT_URL: 'https://chatwoot.xtract.app',
    CHATWOOT_ACCOUNT_ID: '1',
    CHATWOOT_INBOX_ID: '1',
    SLACK_CHANNEL: 'C0BKE2PE7B3', // #consultas-whatsapp
    HORARIO_INICIO_MIN: 9 * 60,   // 09:00 hs ART
    HORARIO_FIN_MIN: 18 * 60 + 30, // 18:30 hs ART
    MIN_MINUTOS_ESPERA: 15        // Solo listar si lleva esperando > 15 min
  }
}];

// =====================================================================
// FILTRO DE HORARIO LABORAL (Hora Argentina UTC-3)
// Lunes (1) a Viernes (5) de 09:00 a 18:30 hs.
// Fuera de horario laboral no se envían recordatorios por Slack.
// =====================================================================
const cfg = $('Config').first().json;
const ahora = new Date();
const fechaArtStr = ahora.toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' });
const fechaArt = new Date(fechaArtStr);
const diaSemana = fechaArt.getDay(); // 0 = Dom, 1 = Lun ... 6 = Sab
const hora = fechaArt.getHours();
const min = fechaArt.getMinutes();
const minutosDelDia = hora * 60 + min;

const esDiaHabil = diaSemana >= 1 && diaSemana <= 5;
const esHorarioLaboral = esDiaHabil && (minutosDelDia >= cfg.HORARIO_INICIO_MIN && minutosDelDia <= cfg.HORARIO_FIN_MIN);

const FORZAR_EJECUCION_TEST = false;

if (!FORZAR_EJECUCION_TEST && !esHorarioLaboral) {
  return []; // Detiene el flujo silenciosamente fuera de horario
}

return [{
  json: {
    es_horario_laboral: true,
    hora_actual_art: hora + ':' + (min < 10 ? '0' + min : min),
    dia_semana: diaSemana
  }
}];

// =====================================================================
// CONSOLIDAR PENDIENTES POR OWNER
// Agrupa todas las conversaciones de Chatwoot abiertas esperando respuesta.
// Si no hay pendientes (0), retorna [] (SILENCIO TOTAL).
// =====================================================================
const cfg = $('Config').first().json;
const raw = $input.first().json || {};
const payload = raw.data?.payload || raw.payload || [];
const lista = Array.isArray(payload) ? payload : [];

const ahoraMs = Date.now();

const SLACK_MEMBERS = {
  'damian.deggeller@xtract.app': 'U09PYEWUHGF',
  'damian deggeller': 'U09PYEWUHGF',
  'damian': 'U09PYEWUHGF',
  'greta.bruno@xtract.app': 'U096BLX5864',
  'greta bruno': 'U096BLX5864',
  'greta': 'U096BLX5864',
  'nicolas.gonzalez@xtract.app': 'U02MCAHHM1T',
  'nicolas gonzalez': 'U02MCAHHM1T',
  'nicolas': 'U02MCAHHM1T',
  'nico': 'U02MCAHHM1T',
  'tomas@xtract.app': 'U01AC8ARHG8',
  'tomas.marconi@xtract.app': 'U01AC8ARHG8',
  'tomas marconi': 'U01AC8ARHG8',
  'tomas': 'U01AC8ARHG8',
  'wenceslao.hoepner@xtract.app': 'U0BBASA0F60',
  'wenceslao hoepner': 'U0BBASA0F60',
  'wenceslao': 'U0BBASA0F60',
  'juan.alvarez@xtract.app': 'U094FGA9VEF',
  'juan alvarez': 'U094FGA9VEF',
  'ian.brandan@xtract.app': 'U09FZ5MLF0E',
  'ian brandan': 'U09FZ5MLF0E'
};

function resolverSlackId(email, nombre) {
  const e = (email || '').toString().toLowerCase().trim();
  const n = (nombre || '').toString().toLowerCase().trim();
  return SLACK_MEMBERS[e] || SLACK_MEMBERS[n] || null;
}

function formatearTiempo(minutos) {
  if (minutos < 60) return `${minutos} min`;
  const h = Math.floor(minutos / 60);
  const m = minutos % 60;
  return m > 0 ? `${h}h ${m}m` : `${h}h`;
}

// Mapa por owner
const porOwner = {};
let totalPendientes = 0;

for (const conv of lista) {
  const labels = Array.isArray(conv.labels) ? conv.labels : [];
  const assignee = conv.meta?.assignee;

  // Solo conversaciones asignadas a un humano o derivadas con 'necesita-humano'
  const esDerivado = labels.includes('necesita-humano') || !!assignee;
  if (!esDerivado) continue;

  const lastMsg = conv.last_non_activity_message;
  if (!lastMsg || lastMsg.private) continue;

  // Si el último mensaje es saliente (comercial ya contestó) -> NO está pendiente
  if (lastMsg.message_type === 1 || lastMsg.sender?.type === 'user') continue;

  // Mensaje entrante del cliente
  const msgTs = typeof lastMsg.created_at === 'number' ? lastMsg.created_at * 1000 : new Date(lastMsg.created_at).getTime();
  if (isNaN(msgTs)) continue;

  const diffMin = Math.floor((ahoraMs - msgTs) / 60000);
  if (diffMin < (cfg.MIN_MINUTOS_ESPERA || 15)) continue; // Ventana inicial de gracia

  const senderObj = conv.meta?.sender || lastMsg.sender || {};
  const clienteNombre = senderObj.name || 'Cliente';
  const clienteTel = senderObj.phone_number || '';
  const empresa = senderObj.custom_attributes?.empresa || '';
  const ownerNombre = assignee?.name || conv.custom_attributes?.owner || 'Sin asignar';
  const ownerEmail = assignee?.email || '';

  const slackId = resolverSlackId(ownerEmail, ownerNombre);
  const ownerMencion = slackId ? `<@${slackId}>` : `*${ownerNombre}*`;

  let textoMsg = (lastMsg.content || '').toString().trim();
  if (textoMsg.length > 150) textoMsg = textoMsg.slice(0, 150) + '…';

  const linkCw = `${cfg.CHATWOOT_URL}/app/accounts/${cfg.CHATWOOT_ACCOUNT_ID}/conversations/${conv.id}`;

  if (!porOwner[ownerMencion]) {
    porOwner[ownerMencion] = [];
  }

  porOwner[ownerMencion].push({
    cliente: clienteNombre,
    empresa: empresa,
    telefono: clienteTel,
    espera: formatearTiempo(diffMin),
    texto: textoMsg || '(Adjunto/audio)',
    link: linkCw
  });

  totalPendientes++;
}

// REGLA DE ORO: SI NO HAY PENDIENTES, SILENCIO TOTAL
if (totalPendientes === 0) {
  return [];
}

// Armar mensaje consolidado
const lineas = [
  `📋 *Recordatorio: Conversaciones de WhatsApp pendientes de respuesta*`,
  `Se detectaron *${totalPendientes}* consulta(s) esperando atención en Chatwoot:\n`
];

for (const [ownerMencion, chats] of Object.entries(porOwner)) {
  lineas.push(`👤 ${ownerMencion} (*${chats.length} pendiente${chats.length > 1 ? 's' : ''}*):`);
  for (const c of chats) {
    const det = c.empresa ? ` (${c.empresa})` : (c.telefono ? ` (${c.telefono})` : '');
    lineas.push(`• *${c.cliente}*${det} — Esperando hace *${c.espera}*`);
    lineas.push(`  💬 _"${c.texto}"_`);
    lineas.push(`  🔗 <${c.link}|Abrir y responder en Chatwoot>`);
  }
  lineas.push('');
}

lineas.push('💡 _Para que salgan de este recordatorio, el comercial debe responder al cliente o marcar el chat como Resuelto en Chatwoot._');

return [{
  json: {
    total: totalPendientes,
    texto_slack: lineas.join('\n'),
    channel: cfg.SLACK_CHANNEL
  }
}];

